  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B028",
      "proposed_laureates": [
        "Franz J. Giessibl",
        "Gerhard Meyer",
        "Leo Gross"
      ],
      "assessment": {
        "nobel_worthiness": "Atomic-resolution qPlus force microscopy made it possible to resolve and chemically identify individual atoms and bonds on surfaces, a major advance in seeing and measuring matter at its smallest scales.",
        "attribution": "Giessibl's development of the qPlus sensor is central; Meyer and Gross helped establish and extend the method's atomic-resolution imaging and chemical sensitivity.",
        "maturity": "The technique has been independently used and refined over decades, with a clear record of experimental capability.",
        "uncertainties": [
          "The distinct Nobel-level contributions of Meyer and Gross relative to Giessibl's original instrument work need careful historical assessment."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B005",
      "proposed_laureates": [
        "Christian Pfleiderer",
        "Roland Wiesendanger",
        "Yoshinori Tokura"
      ],
      "assessment": {
        "nobel_worthiness": "Magnetic skyrmions revealed topologically protected nanoscale spin textures with new physics and potential for compact information storage.",
        "attribution": "Pfleiderer and collaborators identified the skyrmion phase in bulk materials; Wiesendanger's group directly imaged individual skyrmions, while Tokura's work established and broadened the materials platform.",
        "maturity": "The phenomenon has been confirmed across materials and by complementary imaging and scattering methods, though applications remain under development.",
        "uncertainties": [
          "The discovery and subsequent real-space imaging are separable milestones, so the precise balance of credit among the proposed laureates requires review."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B002",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit quantum electrodynamics brought quantum optics into engineered superconducting circuits and became a foundational platform for studying and controlling light–matter interaction at the quantum scale.",
        "attribution": "Blais supplied key theory for the architecture; Wallraff and Schoelkopf led pivotal experiments that demonstrated and established the platform.",
        "maturity": "The basic effects have been replicated, extended to complex systems, and used in rapidly advancing quantum processors.",
        "uncertainties": [
          "The platform developed through broad theoretical and experimental contributions, and the boundary between its foundational demonstration and later quantum computing advances needs care."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B015",
      "proposed_laureates": [
        "B. Jayant Baliga"
      ],
      "assessment": {
        "nobel_worthiness": "The insulated-gate bipolar transistor is a major semiconductor invention that enabled efficient high-power switching across industrial, transport, and energy systems.",
        "attribution": "Baliga's individual contribution is unusually well defined in the candidate record, consistent with recognition of an original device invention.",
        "maturity": "The device has been manufactured and used at scale for decades, with its practical importance firmly established.",
        "uncertainties": [
          "The committee would need to distinguish the prize-worthy invention from the broader, incremental development of power semiconductor technology."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Ioan Mihai Miron",
        "Pietro Gambardella",
        "Robert A. Buhrman"
      ],
      "assessment": {
        "nobel_worthiness": "Spin-orbit torques provided a new way to manipulate magnetic order electrically, opening important physics and device possibilities in spintronics.",
        "attribution": "Miron and Gambardella made central early experimental contributions; Buhrman's work helped establish and develop the effect in other material systems.",
        "maturity": "The effect has been repeatedly demonstrated and is a sustained research and device-development area.",
        "uncertainties": [
          "The early demonstrations were closely timed and used different structures, making priority and the division of credit among these researchers important to verify."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B013",
      "proposed_laureates": [
        "Jie Shan",
        "Kin Fai Mak",
        "Long Ju"
      ],
      "assessment": {
        "nobel_worthiness": "The fractional quantum anomalous Hall effect in moiré materials demonstrates a strongly correlated topological phase without an external magnetic field, a substantial experimental achievement.",
        "attribution": "Shan and Mak led the experiments that established the effect in twisted bilayer systems; Ju's work contributed to the experimental development of the relevant moiré materials platform.",
        "maturity": "The initial observation has prompted rapid follow-up, but this is a young field whose reproducibility and range of realized phases are still being established.",
        "uncertainties": [
          "The discovery is recent, so the record of independent confirmation and the precise contributions to the first observation remain developing."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B019",
      "proposed_laureates": [
        "Henry J. Snaith",
        "Nam-Gyu Park",
        "Tsutomu Miyasaka"
      ],
      "assessment": {
        "nobel_worthiness": "Metal-halide perovskite solar cells transformed photovoltaic research through rapidly improving efficiency and unusual material properties, with a credible path to broad practical benefit.",
        "attribution": "Miyasaka reported early perovskite-sensitized cells, while Park and Snaith made influential advances that established efficient solid-state devices.",
        "maturity": "The laboratory performance is well established, but long-term stability, scale-up, and environmental concerns continue to shape the technology's prospects.",
        "uncertainties": [
          "The progression from early cell demonstrations to high-efficiency devices involved many groups, and the boundary between original discovery and subsequent improvements is contested."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B045",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals introduced the control of light through engineered periodic structures, creating a broad and durable research area with applications in optics and photonics.",
        "attribution": "Yablonovitch and John independently formulated key proposals and physical principles; Joannopoulos was central to the theory and development that made the field coherent and accessible.",
        "maturity": "The predicted effects and numerous device concepts have been experimentally realized, although the field spans several distinct inventions and implementations.",
        "uncertainties": [
          "The parallel origins of the concept and the breadth of subsequent contributions make a sharply bounded discovery and laureate selection difficult."
        ]
      }
    }
  ]
}
